-- au reference-data seed (the 42-area seat model), captured from staging cifwmndunmlxjhyjugxa.
-- Populates the au tables the DDL migrations create (they were loaded on staging via tooling, not a
-- migration). Idempotent: ON CONFLICT DO NOTHING everywhere, FK-safe order (regions -> lines ->
-- canonical_areas -> line map -> crosswalk -> seats [parent-first] -> line_area_map -> occupancy).
-- NOTE: this seeds the au MODEL only. The public.areas transition (insert the 42 canonical + remap
-- old area_id across modules + retire legacy areas) is production-data-specific and is handled by a
-- separate, purpose-built Phase-9 cutover migration — NOT a replay of staging's execute_sql fixes.

on conflict (region_code) do nothing;

on conflict (line_code) do nothing;

on conflict (area_code) do nothing;

on conflict (official_line) do nothing;

on conflict (sos_area_code) do nothing;

on conflict (seat_id) do nothing;

on conflict (line_code, area_code) where effective_to is null do nothing;

on conflict (seat_id) where effective_to is null do nothing;
